const $=s=>document.querySelector(s),app=$('#app'),notice=$('#notice'),dialog=$('#detail');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state={config:null,home:null,activity:null,board:null,className:'',cursor:null,busy:false,dirty:false,termView:null,termData:null,issued:null,classes:[],roster:[],workFilter:'all',query:'',studentView:'work'};
