const button=(label,action,data='',secondary=false)=>`<button type="button" ${secondary?'class="secondary"':''} data-action="${action}" ${data}>${label}</button>`;
async function api(action,data={},write=false){const response=await previewFetch('/api/workspace'+(write?'':'?'+new URLSearchParams({action,...data})),{method:write?'POST':'GET',credentials:'same-origin',headers:write?{'Content-Type':'application/json'}:{},...(write?{body:JSON.stringify({action,...data})}:{})});const payload=await response.json();if(!payload.ok)throw new Error(payload.error||'暫時無法完成，請稍後再試。');return payload.data;}
function say(s,error=false){notice.textContent=s;notice.className=error?'error':'';}
function show(html){$('#detailBody').innerHTML=html;const title=$('#detailBody h2');if(title){title.id='dialogTitle';dialog.setAttribute('aria-labelledby','dialogTitle');}if(!dialog.open)dialog.showModal();dialog.scrollTop=0;}
function heading(title,subtitle='',kind=''){document.querySelector('#learningBrief').innerHTML=isW8({kind})?'<details><summary>本週學習重點</summary>'+learningBrief(kind)+'</details>':learningBrief(kind);document.querySelector('.intro h1').textContent=title;$('#pageSubtitle').textContent=subtitle;document.title=title+'｜閱讀理解與表達';}
$('#closeDialog').onclick=()=>{if(state.busy)return;if(state.dirty&&!confirm('內容還沒送出。確定關閉？'))return;state.dirty=false;dialog.close();};
dialog.addEventListener('cancel',e=>{if(state.busy||state.dirty)e.preventDefault();});
document.addEventListener('input',e=>{if(e.target.closest('#detail'))state.dirty=true;});
window.addEventListener('beforeunload',e=>{if(state.busy||state.dirty){e.preventDefault();e.returnValue='';}});
async function guard(fn){if(state.busy)return;state.busy=true;document.body.classList.add('busy');app.setAttribute('aria-busy','true');const active=document.activeElement,btn=active?.tagName==='BUTTON'?active:null;if(btn)btn.disabled=true;try{await fn();}catch(e){say(e.message,true);const inline=$('#formStatus');if(inline)inline.textContent=e.message;}finally{state.busy=false;document.body.classList.remove('busy');app.removeAttribute('aria-busy');if(btn?.isConnected)btn.disabled=false;}}
